import { Component, h, Prop, Element, Host } from '@stencil/core';

const prefix = 'skeleton-tile';

@Component({
  tag: 'ks-skeleton-tile',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsSkeletonTile {
  ['x-name'] = 'ks-skeleton-tile';
  @Element() el!: HTMLKsSkeletonTileElement;
  /** The number of body text lines to render in the skeleton tile, excluding the title line. */
  @Prop() rows = 2;

  /** The width of the title line within the skeleton tile (e.g., "80px", "30%"). */
  @Prop() titleWidth = '80px';

  render() {
    // const cls = classnames('ks-skeleton', prefix, `${prefix}`);
    return (
      <Host class="KsSkeletonTile" aria-hidden="true">
        <div class={prefix}>
          <ks-skeleton-text style={{ width: this.titleWidth }} variant="titleLg" />
          {Array.from({ length: this.rows }).map(() => (
            <ks-skeleton-text style={{ width: '100%' }} variant="bodyMd" />
          ))}
        </div>
      </Host>
    );
  }
}
